abstract final class EnglishAdvancedB1SevenToTen {
 static const lessons=<EnglishAdvancedLesson>[
EnglishAdvancedLesson(level:'B1',unitNumber:1,number:7,title:"A Small Business Idea",titleArabic:"فكرة مشروع صغير",storyTitle:"A Small Business Idea",storyTitleArabic:"فكرة مشروع صغير",paragraphs:<String>["Farah noticed that office workers often skipped breakfast. She imagined a bicycle cart selling healthy snacks near a busy square. Before investing her savings, she interviewed potential customers and carried out a short pricing survey.","She wrote a business plan and calculated the start-up costs. A retired shopkeeper offered to become her mentor, and she compared several suppliers before choosing ingredients for a trial menu. The council explained how she could obtain a trading licence.","The first week was difficult because an early delivery arrived late. One customer complained about cold food, so Farah offered a fresh substitute and adjusted the preparation schedule. She learned that complaints can be an opportunity to build trust.","By the end of the month, she had earned enough profit to reinvest in a better bicycle cart. She planned to employ a part-time helper but promised herself to expand carefully rather than rush into expensive decisions."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bicycle cart","عربة دراجة"),EnglishAdvancedWord("potential customers","زبائن محتملون"),EnglishAdvancedWord("pricing survey","استبيان أسعار"),EnglishAdvancedWord("business plan","خطة عمل"),EnglishAdvancedWord("start-up costs","تكاليف تأسيس"),EnglishAdvancedWord("mentor","مرشد"),EnglishAdvancedWord("suppliers","موردون"),EnglishAdvancedWord("trial menu","قائمة تجريبية"),EnglishAdvancedWord("trading licence","ترخيص تجاري"),EnglishAdvancedWord("fresh substitute","بديل طازج"),EnglishAdvancedWord("preparation schedule","جدول إعداد"),EnglishAdvancedWord("reinvest","يعيد استثمار")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("market demand","طلب السوق"),EnglishAdvancedWord("pricing strategy","استراتيجية تسعير"),EnglishAdvancedWord("cash flow","تدفق نقدي"),EnglishAdvancedWord("small enterprise","منشأة صغيرة"),EnglishAdvancedWord("operating expense","مصروف تشغيل"),EnglishAdvancedWord("local competitor","منافس محلي"),EnglishAdvancedWord("business registration","تسجيل مشروع"),EnglishAdvancedWord("inventory tracking","تتبع المخزون"),EnglishAdvancedWord("customer loyalty","ولاء الزبائن"),EnglishAdvancedWord("sales forecast","توقع المبيعات"),EnglishAdvancedWord("daily turnover","إيراد يومي"),EnglishAdvancedWord("food hygiene","نظافة الطعام"),EnglishAdvancedWord("supplier contract","عقد توريد"),EnglishAdvancedWord("break-even point","نقطة التعادل"),EnglishAdvancedWord("growth potential","إمكانات نمو"),EnglishAdvancedWord("product testing","اختبار المنتج"),EnglishAdvancedWord("business ownership","ملكية المشروع"),EnglishAdvancedWord("quality control","ضبط الجودة")],grammarTitle:"Gerunds and infinitives for plans",grammarArabic:"بعد decide وplan نستخدم to + فعل: She decided to start a business. وبعد enjoy نستخدم الفعل مع ing: She enjoys meeting customers. لاحظ الفرق بين الأفعال التي يتبعها المصدر والأفعال التي يتبعها ing.",grammarExamples:<String>["She decided to launch her business.","Farah enjoyed talking to customers.","Her mentor suggested testing one menu."],listening:"Our business workshop begins at eight thirty on Monday. First, you will identify your potential customers and prepare a simple budget. Then our mentor will explain the importance of choosing reliable suppliers and keeping records. Participants should bring a short description of their idea and an estimate of start-up costs. During the afternoon session, local shopkeepers will describe mistakes they made and how they corrected them. Please remember that starting small is often less risky than making a large investment before testing demand.",listeningQuestion:"Why does the speaker advise starting small?",listeningOptions:<String>["To avoid customers","To reduce early financial risk","To skip planning"],listeningAnswer:1,readingQuestion:"What did Farah do after the customer complained?",readingOptions:<String>["She ignored the complaint","She offered a fresh substitute","She closed the cart"],readingAnswer:1,writingCue:"Farah decided to ____ some profits into her shop.",writingAnswer:"reinvest"),
EnglishAdvancedLesson(level:'B1',unitNumber:1,number:8,title:"Organizing a Charity Run",titleArabic:"تنظيم سباق خيري",storyTitle:"Organizing a Charity Run",storyTitleArabic:"تنظيم سباق خيري",paragraphs:<String>["The sports club planned a charity run to raise money for a children's hospital. Omar volunteered as route marshal, mapped a safe course through the park and placed signposts near difficult turns. He asked the first-aid team to review the plan.","Registration opened online, and each participant received a bib number. Local businesses donated refreshments, while a photographer offered to record celebrations at the start and at the end of the run.","Early that morning, strong winds damaged the start banner. Organizers quickly repaired it, but the delay worried several families. Omar used the public-address system to explain the change clearly and directed runners to the warm-up area.","The event collected more donations than expected. Volunteers packed equipment after the final runners arrived, and Omar thanked everyone who had supported the hospital. He understood that careful preparation mattered just as much as enthusiasm."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("charity run","سباق خيري"),EnglishAdvancedWord("children's hospital","مستشفى أطفال"),EnglishAdvancedWord("route marshal","منظم المسار"),EnglishAdvancedWord("safe course","مسار آمن"),EnglishAdvancedWord("signposts","لافتات اتجاه"),EnglishAdvancedWord("first-aid team","فريق إسعافات"),EnglishAdvancedWord("registration","التسجيل"),EnglishAdvancedWord("participant","مشارك"),EnglishAdvancedWord("bib number","رقم سباق"),EnglishAdvancedWord("refreshments","مرطبات"),EnglishAdvancedWord("start banner","لافتة انطلاق"),EnglishAdvancedWord("public-address system","نظام النداء")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("event insurance","تأمين الفعالية"),EnglishAdvancedWord("checkpoint","نقطة تحقق"),EnglishAdvancedWord("sponsorship pledge","تعهد رعاية"),EnglishAdvancedWord("hydration station","محطة مياه"),EnglishAdvancedWord("race steward","مراقب سباق"),EnglishAdvancedWord("running pace","وتيرة الجري"),EnglishAdvancedWord("safety briefing","إحاطة سلامة"),EnglishAdvancedWord("volunteer shift","نوبة تطوع"),EnglishAdvancedWord("medical tent","خيمة طبية"),EnglishAdvancedWord("route diversion","تغيير مسار"),EnglishAdvancedWord("crowd barrier","حاجز جمهور"),EnglishAdvancedWord("weather alert","تنبيه الطقس"),EnglishAdvancedWord("donor receipt","إيصال تبرع"),EnglishAdvancedWord("event timetable","جدول الفعالية"),EnglishAdvancedWord("community partner","شريك محلي"),EnglishAdvancedWord("fundraising total","مجموع التبرعات"),EnglishAdvancedWord("post-race survey","استطلاع بعد السباق"),EnglishAdvancedWord("participation certificate","شهادة مشاركة")],grammarTitle:"Modals for rules and advice",grammarArabic:"نستخدم must وhave to للإلزام، وshould للنصيحة. Mustn't تعني أن الفعل ممنوع، بينما don't have to تعني أنه غير ضروري.",grammarExamples:<String>["Runners must wear their numbers.","Volunteers have to arrive early.","You should drink plenty of water."],listening:"Attention, runners. The charity race will begin fifteen minutes late because a barrier must be moved near the northern entrance. Everyone must wear a bib number clearly. If you feel unwell, please visit the medical tent beside the lake. Water is available at two checkpoints, but you should carry your own bottle. Spectators must stay behind the marked barriers. The organizers will make a further announcement when the route is ready. Thank you for supporting our hospital fundraiser.",listeningQuestion:"Why has the race start been delayed?",listeningOptions:<String>["A barrier must be moved","There are no runners","The hospital is closed"],listeningAnswer:0,readingQuestion:"How did Omar inform the runners about the delay?",readingOptions:<String>["By closing the park","Using a public-address system","By sending letters"],readingAnswer:1,writingCue:"Each runner wore a ____ during the charity event.",writingAnswer:"bib number"),
EnglishAdvancedLesson(level:'B1',unitNumber:1,number:9,title:"The Community Garden",titleArabic:"حديقة الحي المشتركة",storyTitle:"The Community Garden",storyTitleArabic:"حديقة الحي المشتركة",paragraphs:<String>["Residents proposed a shared garden on an abandoned lot behind their apartment buildings. Leila attended the planning meeting and asked about the water supply. She wanted enough sunlight for vegetables and a pleasant place where neighbors could meet.","At the first workday, volunteers built raised beds and carried out soil testing. A local gardener demonstrated crop rotation, and a young family offered to maintain a compost bin for fallen leaves and vegetable waste.","Not everyone liked the initial design. Some parents wanted a play area, while others preferred more planting space. Leila suggested a separate section for each activity and made a work schedule so volunteers could share the tasks fairly.","By autumn, children were helping with the harvest, and the new pathways were full of visitors. The garden had changed more than the appearance of the street: it encouraged neighbors to solve problems together."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("shared garden","حديقة مشتركة"),EnglishAdvancedWord("abandoned lot","أرض مهجورة"),EnglishAdvancedWord("planning meeting","اجتماع تخطيط"),EnglishAdvancedWord("water supply","إمداد مياه"),EnglishAdvancedWord("sunlight","ضوء الشمس"),EnglishAdvancedWord("raised beds","أحواض زراعة مرتفعة"),EnglishAdvancedWord("soil testing","اختبار تربة"),EnglishAdvancedWord("crop rotation","تناوب محاصيل"),EnglishAdvancedWord("compost bin","حاوية سماد"),EnglishAdvancedWord("play area","منطقة لعب"),EnglishAdvancedWord("work schedule","جدول عمل"),EnglishAdvancedWord("harvest","حصاد")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("irrigation hose","خرطوم ري"),EnglishAdvancedWord("seedling","شتلة"),EnglishAdvancedWord("allotment","قطعة زراعية"),EnglishAdvancedWord("rainwater barrel","برميل مطر"),EnglishAdvancedWord("garden coordinator","منسق الحديقة"),EnglishAdvancedWord("seasonal planting","زراعة موسمية"),EnglishAdvancedWord("vegetable plot","قطعة خضار"),EnglishAdvancedWord("mulching","تغطية التربة"),EnglishAdvancedWord("pollinator plants","نباتات ملقحة"),EnglishAdvancedWord("shared tools","أدوات مشتركة"),EnglishAdvancedWord("maintenance rota","جدول صيانة"),EnglishAdvancedWord("urban biodiversity","تنوع أحيائي حضري"),EnglishAdvancedWord("soil nutrients","مغذيات التربة"),EnglishAdvancedWord("pest management","إدارة الآفات"),EnglishAdvancedWord("neighborhood council","مجلس الحي"),EnglishAdvancedWord("garden entrance","مدخل الحديقة"),EnglishAdvancedWord("produce exchange","تبادل المحصول"),EnglishAdvancedWord("volunteer gardener","بستاني متطوع")],grammarTitle:"Defining relative clauses",grammarArabic:"نستخدم who عند وصف الأشخاص وwhich أو that للأشياء في جمل الصلة: The neighbor who helped us was kind. The beds that we built were strong. تساعد الجملة في تحديد الشخص أو الشيء المقصود.",grammarExamples:<String>["The gardener who helped us was experienced.","The tools that we shared were clean.","The area which faces south gets more light."],listening:"The garden committee has approved the planting plan. The eastern section will grow vegetables, while the western section will contain flowers and a small children's play area. Volunteers who are free on Saturday should meet at the main entrance at eight thirty. We have tested the soil already, but we need help filling the raised beds with fresh compost. Anyone who cannot attend may donate seeds or choose a later watering shift. The committee will review progress at the end of the month.",listeningQuestion:"What will grow in the eastern section?",listeningOptions:<String>["Vegetables","Only trees","Only flowers"],listeningAnswer:0,readingQuestion:"What did Leila suggest to solve the disagreement?",readingOptions:<String>["Canceling the garden","Separating the space by activity","Refusing volunteers"],readingAnswer:1,writingCue:"The garden grew many vegetables ready for the ____.",writingAnswer:"harvest"),
EnglishAdvancedLesson(level:'B1',unitNumber:1,number:10,title:"Making a Difficult Choice",titleArabic:"اتخاذ قرار صعب",storyTitle:"Making a Difficult Choice",storyTitleArabic:"اتخاذ قرار صعب",paragraphs:<String>["Yara received two university offers and was pleased but uncertain. One institution offered a generous scholarship and a familiar campus, while the other included practical placements in a distant city. She listed the advantages and disadvantages of each option.","Her cousin advised her to consider long-term goals before deciding. Yara visited both universities and asked students about accommodation, the course workload and career prospects. The answers helped her understand what daily life would be like.","An unexpected deadline made everything more stressful. Yara accepted that every decision involved uncertainty and asked which place would support her ambitions best over several years. She wanted an education that included practical experience, not only good examination results.","In the end, Yara chose the university offering placements. Although she would miss her family, she knew the programme suited her future plans. Her parents supported her, and she felt more confident about facing a new environment."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("university offers","عروض جامعية"),EnglishAdvancedWord("uncertain","غير متأكد"),EnglishAdvancedWord("scholarship","منحة دراسية"),EnglishAdvancedWord("campus","حرم جامعي"),EnglishAdvancedWord("practical placements","تدريبات عملية"),EnglishAdvancedWord("advantages","مزايا"),EnglishAdvancedWord("disadvantages","عيوب"),EnglishAdvancedWord("long-term goals","أهداف بعيدة"),EnglishAdvancedWord("accommodation","سكن"),EnglishAdvancedWord("course workload","عبء دراسة"),EnglishAdvancedWord("career prospects","آفاق مهنية"),EnglishAdvancedWord("ambitions","طموحات")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("degree programme","برنامج درجة"),EnglishAdvancedWord("academic adviser","مرشد أكاديمي"),EnglishAdvancedWord("tuition fees","رسوم الدراسة"),EnglishAdvancedWord("student loan","قرض دراسي"),EnglishAdvancedWord("living expenses","تكاليف المعيشة"),EnglishAdvancedWord("career pathway","مسار وظيفي"),EnglishAdvancedWord("admission offer","عرض قبول"),EnglishAdvancedWord("application deadline","موعد انتهاء التقديم"),EnglishAdvancedWord("work experience","خبرة عملية"),EnglishAdvancedWord("personal priorities","أولويات شخصية"),EnglishAdvancedWord("decision matrix","مصفوفة قرار"),EnglishAdvancedWord("family expectations","توقعات العائلة"),EnglishAdvancedWord("future earnings","أرباح مستقبلية"),EnglishAdvancedWord("independent living","معيشة مستقلة"),EnglishAdvancedWord("student support","دعم الطلبة"),EnglishAdvancedWord("internship placement","موقع تدريب"),EnglishAdvancedWord("academic reputation","سمعة أكاديمية"),EnglishAdvancedWord("study environment","بيئة الدراسة")],grammarTitle:"Contrast with although, despite and however",grammarArabic:"تأتي although مع جملة كاملة: Although the city was far away, she applied. أما despite فتأتي قبل اسم أو فعل منتهٍ بـ ing: Despite the distance, she accepted. وتربط however بين فكرتين متقابلتين.",grammarExamples:<String>["Although she was uncertain, she decided.","Despite the distance, she chose that course.","The offer was generous; however, it was far away."],listening:"Hello, Yara. I am calling from the university admissions office about your offer. Your scholarship will cover tuition fees, but it will not cover rent or travel. To keep the scholarship you must accept your place before five o'clock on Friday. If you have questions about accommodation, our student adviser can meet you tomorrow morning. We can also send details about practical training by email. Please note that an extension to the deadline is not guaranteed.",listeningQuestion:"Which costs will the scholarship pay?",listeningOptions:<String>["Rent and transport","Tuition fees","Every living expense"],listeningAnswer:1,readingQuestion:"Why did Yara finally select the distant university?",readingOptions:<String>["Its placements supported her goals","Her cousin ordered her","She disliked studying"],readingAnswer:0,writingCue:"Yara received a ____ to help pay for her course.",writingAnswer:"scholarship")
 ];
}
